CREATE SCHEMA soil;
REVOKE CREATE ON SCHEMA public FROM PUBLIC;
CREATE TABLE soil.release (id text PRIMARY KEY, manifest jsonb NOT NULL);
CREATE TABLE soil.active_release (singleton boolean PRIMARY KEY DEFAULT true CHECK (singleton), release_id text NOT NULL REFERENCES soil.release(id));
CREATE TABLE soil.component (release_id text NOT NULL REFERENCES soil.release(id), ordinal bigint NOT NULL, mukey bigint, cokey bigint, compname text, comppct_r numeric, albedodry_r numeric, hydricrating text, drainagecl text, taxclname text, geomdesc text, taxorder text, taxsuborder text);
CREATE INDEX component_lookup ON soil.component (release_id, mukey, ordinal);
CREATE TABLE soil.chorizon (release_id text NOT NULL REFERENCES soil.release(id), ordinal bigint NOT NULL, cokey bigint, chkey bigint, hzname text, hzdepb_r numeric, hzdept_r numeric, hzthk_r numeric, dbthirdbar_r numeric, ksat_r numeric, sandtotal_r numeric, claytotal_r numeric, om_r numeric, cec7_r numeric, awc_l numeric, fraggt10_r numeric, frag3to10_r numeric, desgnmaster text, sieveno10_r numeric, wthirdbar_r numeric, wfifteenbar_r numeric, sandvf_r numeric, ll_r numeric);
CREATE INDEX chorizon_lookup ON soil.chorizon (release_id, cokey, ordinal);
CREATE TABLE soil.chfrags (release_id text NOT NULL REFERENCES soil.release(id), ordinal bigint NOT NULL, chkey bigint, fragvol_r numeric);
CREATE INDEX chfrags_lookup ON soil.chfrags (release_id, chkey, ordinal);
CREATE TABLE soil.chtexturegrp (release_id text NOT NULL REFERENCES soil.release(id), ordinal bigint NOT NULL, chkey bigint, texture text);
CREATE INDEX chtexturegrp_lookup ON soil.chtexturegrp (release_id, chkey, ordinal);
CREATE TABLE soil.corestrictions (release_id text NOT NULL REFERENCES soil.release(id), ordinal bigint NOT NULL, cokey bigint, reskind text);
CREATE INDEX corestrictions_lookup ON soil.corestrictions (release_id, cokey, ordinal);
CREATE TABLE soil.muaggatt (release_id text NOT NULL REFERENCES soil.release(id), ordinal bigint NOT NULL, mukey bigint, muname text, wtdepannmin numeric, flodfreqdcd text, aws025wta numeric, aws0150wta numeric, hydgrpdcd text, drclassdcd text);
CREATE INDEX muaggatt_lookup ON soil.muaggatt (release_id, mukey, ordinal);
CREATE UNIQUE INDEX muaggatt_unique ON soil.muaggatt(release_id,mukey);
GRANT USAGE ON SCHEMA soil TO soil_serve;
GRANT SELECT ON ALL TABLES IN SCHEMA soil TO soil_serve;
